 -- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Anweisungen des Arbeitgebers befolgen (§ 13 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker die Anweisungen seines Ausbilders befolgen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG verpflichtet dazu"}, {"text": "Nein", "correct": false, "because": "Gehorsam ist eine gesetzliche Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker Anweisungen ignorieren, wenn er sie für falsch hält?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG fordert Befolgung, außer bei illegalen Anweisungen"}, {"text": "Ja", "correct": false, "because": "Ignorieren widerspricht der Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, eine Programmieraufgabe nach Anweisung des Ausbilders zu lösen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG umfasst betriebliche Anweisungen"}, {"text": "Nein", "correct": false, "because": "Anweisungen sind bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker Anweisungen des Arbeitgebers ablehnen, wenn sie gefährlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Gefährliche Anweisungen müssen nicht befolgt werden"}, {"text": "Nein", "correct": false, "because": "Ablehnung nur bei Gefahr zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker auch Anweisungen befolgen, die nicht direkt mit IT zu tun haben?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG gilt für alle betrieblichen Anweisungen"}, {"text": "Nein", "correct": false, "because": "Pflicht umfasst alle Anweisungen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker, Anweisungen des Arbeitgebers zu befolgen?', 2, '[{"text": "§ 13 BBiG", "correct": true, "because": "Regelt die Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er eine Anweisung nicht versteht?', 3, '[{"text": "Den Ausbilder um Klärung bitten", "correct": true, "because": "§ 13 BBiG fordert Mitwirkung"}, {"text": "Die Anweisung ignorieren", "correct": false, "because": "Widerspricht der Pflicht"}, {"text": "Sofort kündigen", "correct": false, "because": "Zu drastisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anweisung muss ein Fachinformatiker befolgen?', 3, '[{"text": "Eine Software nach Vorgaben programmieren", "correct": true, "because": "Entspricht § 13 BBiG"}, {"text": "Illegale Daten manipulieren", "correct": false, "because": "Illegale Anweisungen sind ausgenommen"}, {"text": "Private Einkäufe für den Chef erledigen", "correct": false, "because": "Nicht betriebsbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer hat das Weisungsrecht gegenüber einem Fachinformatiker?', 2, '[{"text": "Der Ausbilder", "correct": true, "because": "§ 14 Abs. 2 BBiG regelt das Weisungsrecht"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat kein Weisungsrecht"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker Anweisungen wiederholt nicht befolgt?', 3, '[{"text": "Er kann abgemahnt oder gekündigt werden", "correct": true, "because": "Verstoß gegen § 13 BBiG hat Folgen"}, {"text": "Der Betrieb übernimmt die Aufgaben", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Die IHK greift ein", "correct": false, "because": "Nur bei Beschwerde möglich"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Anweisungen muss ein Fachinformatiker gemäß § 13 BBiG befolgen?', 4, '[{"text": "Programmieraufgaben nach Vorgabe", "correct": true, "because": "Betriebsbezogen"}, {"text": "Netzwerkwartung durchführen", "correct": true, "because": "Teil der Ausbildung"}, {"text": "Illegale Software installieren", "correct": false, "because": "Illegale Anweisungen ausgenommen"}, {"text": "Betriebsinterne Regeln einhalten", "correct": true, "because": "Pflicht gemäß § 13 BBiG"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen darf ein Fachinformatiker Anweisungen nicht befolgen?', 3, '[{"text": "Wenn sie illegal sind", "correct": true, "because": "Illegale Anweisungen sind ausgenommen"}, {"text": "Wenn sie gefährlich sind", "correct": true, "because": "Gefahr rechtfertigt Ablehnung"}, {"text": "Wenn er sie nicht mag", "correct": false, "because": "Persönliche Meinung irrelevant"}, {"text": "Wenn sie außerhalb der Arbeitszeit liegen", "correct": false, "because": "Arbeitszeit ist separat geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Pflicht eines Fachinformatikers, Anweisungen zu befolgen?', 4, '[{"text": "Anweisungen pünktlich umsetzen", "correct": true, "because": "§ 13 BBiG fordert Zuverlässigkeit"}, {"text": "Klarstellung bei Unklarheiten suchen", "correct": true, "because": "Verantwortliches Verhalten"}, {"text": "Nur eigene Methoden anwenden", "correct": false, "because": "Anweisungen sind bindend"}, {"text": "Betriebliche Vorgaben einhalten", "correct": true, "because": "Teil der Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei Nichtbefolgung von Anweisungen?', 3, '[{"text": "Abmahnung durch den Betrieb", "correct": true, "because": "Reaktion auf Pflichtverletzung"}, {"text": "Kündigung bei schwerem Verstoß", "correct": true, "because": "§ 22 BBiG erlaubt dies"}, {"text": "Automatische Vertragsauflösung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Meldung an die IHK", "correct": true, "because": "Bei schwerwiegenden Fällen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anweisungen darf ein Fachinformatiker ablehnen?', 3, '[{"text": "Illegale Datenmanipulation", "correct": true, "because": "Illegale Anweisungen ausgenommen"}, {"text": "Gefährliche Hardware-Installation", "correct": true, "because": "Gefahr rechtfertigt Ablehnung"}, {"text": "Programmierung nach Vorgabe", "correct": false, "because": "Betriebsbezogen und zulässig"}, {"text": "Netzwerkkonfiguration ändern", "correct": false, "because": "Teil der Aufgaben"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker muss Anweisungen des Ausbilders befolgen. b) Er darf Anweisungen ignorieren, wenn sie ihm nicht passen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Befolgung ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 13 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anweisungen des Arbeitgebers sind bindend. b) Illegale Anweisungen müssen befolgt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anweisungen sind bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker muss Anweisungen zur Netzwerkwartung befolgen. b) Anweisungen gelten nur in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anweisungen sind immer bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker darf gefährliche Anweisungen ablehnen. b) Anweisungen des Arbeitgebers sind freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gefahr erlaubt Ablehnung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 13 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anweisungen des Arbeitgebers müssen betriebsbezogen sein. b) Ein Fachinformatiker muss private Anweisungen befolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anweisungen müssen betrieblich sein, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

